<style>
  * { margin:0; padding:0; box-sizing:border-box; }
  html,body { height:100%; overflow:hidden; background:#1a1c2c; }
  body { display:flex; align-items:center; justify-content:center; font-family:'Press Start 2P', monospace; }
  #wrap { position:relative; width:min(96vw, 960px); }
  canvas { display:block; width:100%; height:auto; image-rendering:auto; border:4px solid #0f0f1a; border-radius:10px; box-shadow:0 0 0 4px #3c3f5a, 0 20px 60px #000; cursor:crosshair; background:#2b2d42; }
  #hud { position:absolute; top:10px; left:12px; right:12px; display:flex; justify-content:space-between; pointer-events:none; color:#fff; text-shadow:2px 2px 0 #000; font-size:12px; }
  #overlay { position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; background:rgba(10,10,20,.78); border-radius:10px; color:#fff; text-align:center; padding:20px; transition:opacity .25s; }
  #overlay.hidden { opacity:0; pointer-events:none; }
  #overlay h1 { font-size:clamp(18px,4vw,34px); color:#ffd23f; text-shadow:3px 3px 0 #b5541f; margin-bottom:18px; line-height:1.5; }
  #overlay p { font-size:11px; line-height:2; color:#cdd2ff; margin-bottom:22px; }
  button { font-family:inherit; font-size:14px; padding:14px 26px; background:#ffd23f; color:#301d00; border:0; border-radius:8px; cursor:pointer; box-shadow:0 5px 0 #b5541f; }
  button:active { transform:translateY(4px); box-shadow:0 1px 0 #b5541f; }
  #final { color:#7dff9b; font-size:20px; margin-bottom:14px; display:none; }
</style>
</head>
